"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["26211"],{88512(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.envelope_codec.versao_desconhecida","status":422,"titulo":"O sistema n\xe3o reconhece a vers\xe3o da configura\xe7\xe3o publicada"},"descricao":{"codigo":"uniplus.selecao.envelope_codec.versao_desconhecida","requisitos":["UNI-REQ-0019"],"oQueAconteceu":["Ao publicar um processo seletivo, o sistema guarda sua configura\xe7\xe3o junto da vers\xe3o do formato usada. Esta recusa indica que o sistema atual n\xe3o conhece essa vers\xe3o e n\xe3o consegue recuperar a configura\xe7\xe3o.","Isso pode ocorrer ap\xf3s uma atualiza\xe7\xe3o do formato. A mensagem informa que a vers\xe3o do formato n\xe3o \xe9 reconhecida. O sistema recusa a leitura antes de a opera\xe7\xe3o em curso, como retificar ou conferir os dados coletados, prosseguir, para evitar apresentar uma configura\xe7\xe3o diferente da publicada."],"comoResolver":["Acione o suporte, informando o `instance` e o `traceId` do ProblemDetails recebido. O processo foi congelado por uma vers\xe3o do formato que o sistema n\xe3o l\xea mais, e nada que se edite na tela muda isso: a leitura desse processo depende da equipe respons\xe1vel pelo sistema. Com o suporte acionado, o processo permanece como estava, sem altera\xe7\xe3o, at\xe9 a an\xe1lise."],"ondeAparece":["Leitura da configura\xe7\xe3o publicada do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Envelope codec"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"3bbcc2307827ee8c6dab135295710bb856847f61"}}')}}]);